'use strict';

// Shared views use the same session and server permissions as the core workspace.
S.ws={account:null,threadId:null,threads:[],messages:[],chatContext:null,chatBusy:false,chatDraft:'',planning:null,audit:null,selection:[],planningCheck:null,planStudent:null,planTerm:null,offeringQuery:'',offeringFilter:'all',offeringsPage:1,taskFilter:'active',overlayTicket:0};
const planStatus={draft:'已保存草案',submitted:'已提交辅导员',approved:'辅导员已认可',revision:'需要调整'};
const taskSources={self:'我的计划',assistant:'采纳的建议',counselor:'辅导员安排'};
const safeLink=v=>{if(typeof v!=='string'||!v.trim())return null;const value=v.trim();if(!/^https?:\/\//i.test(value)&&!/^\/(?!\/)/.test(value))return null;try{const u=new URL(value,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
const textValue=v=>typeof v==='string'?v:(v==null?'':JSON.stringify(v));
const apiStudent=id=>'/api/students/'+encodeURIComponent(id);
const checkIcon=met=>ico(met?'check':'alert');
function followupDraftKey(id){return 'zhixue.followup.'+S.user.id+'.'+id;}
function stashFollowupDraft(){const form=$('#followup');if(!form||form.dataset.draftDirty!=='true'||!S.user)return;const draft=Object.fromEntries(new FormData(form));try{sessionStorage.setItem(followupDraftKey(form.dataset.id),JSON.stringify(draft));}catch{S.ws.followupDrafts??={};S.ws.followupDrafts[followupDraftKey(form.dataset.id)]=draft;}}
function clearFollowupDraft(id){try{sessionStorage.removeItem(followupDraftKey(id));}catch{}if(S.ws.followupDrafts)delete S.ws.followupDrafts[followupDraftKey(id)];}
function restoreFollowupDraft(){const form=$('#followup');if(!form)return;let draft;try{draft=JSON.parse(sessionStorage.getItem(followupDraftKey(form.dataset.id))||'null');}catch{}draft??=S.ws.followupDrafts?.[followupDraftKey(form.dataset.id)];if(!draft)return;for(const name of ['status','note','plan','reviewOn']){const input=form.elements.namedItem(name);if(!input)continue;if(name==='status'&&![...input.options].some(o=>o.value===draft[name]))continue;input.value=draft[name]||'';}form.dataset.draftDirty='true';const notice=document.createElement('div');notice.className='tip space-b';notice.innerHTML='已恢复本次浏览器会话中尚未提交的跟进草稿。<button class="btn link" style="margin-left:12px" data-action="discard-followup-draft">清除草稿</button>';form.prepend(notice);}

function allocationCourses(a){return a.allocatableCourses||a.unassignedCourses||[];}
function validAllocations(allocations,modules,selected){const ids=new Set(modules.map(m=>m.id)),chosen=new Set(selected);return Object.fromEntries(Object.entries(allocations).filter(([,bucket])=>!ids.has(bucket)||chosen.has(bucket)));}
function allocationManager(a,readOnly){const courses=allocationCourses(a),pref=a.preferences||{},moduleNames=Object.fromEntries((a.advancedModules||[]).map(m=>[m.id,m.name]));const label=id=>moduleNames[id]||({innovation:'创新创业',cross:'专业交叉',free:'自选课程'}[id])||id;if(!courses.length)return '';return `<details class="tool-trace allocation-manager" style="margin-top:17px"><summary>课程学分归属管理（${courses.length} 门）</summary><div class="tool-steps"><p class="small muted">可以查看、修改或清除已有手动分配。同一门课程只计入一个归属；选择“按当前路线自动核算”会清除手动分配。</p><label class="search" style="display:block;margin:13px 0">${ico('search')}<input class="field" id="allocation-query" placeholder="搜索课程名称" aria-label="搜索归属课程"></label><div class="allocation-list">${courses.map(c=>`<label class="form-item allocation-row" data-search="${html(c.name.toLowerCase())}" data-course-label="${html(c.name)}" style="margin-top:13px"><span>${html(c.name)} · ${c.credits} 学分 <small class="muted">${c.passed?'已通过':'未通过或未修'}${c.allocatedTo?' · 当前计入 '+html(label(c.allocatedTo)):''}</small></span><select name="allocation:${html(c.id)}" ${readOnly?'disabled':''}><option value="">按当前路线自动核算</option>${(c.eligibleModules||[]).map(v=>{const id=typeof v==='object'?v.id:v;return `<option value="${html(id)}" ${pref.allocations?.[c.id]===id?'selected':''} ${(a.advancedModules||[]).some(m=>m.id===id)&&!(pref.advancedModules||[]).includes(id)?'disabled':''}>${html(typeof v==='object'?v.name:label(id))}</option>`;}).join('')}</select></label>`).join('')}</div><div id="allocation-summary" class="source" aria-live="polite"></div></div></details>`;}
function filterAllocationRows(query){$$('.allocation-row').forEach(row=>{row.hidden=!row.dataset.search.includes(query.toLowerCase());});}
function reconcileAllocations(){const form=$('#curriculum-preferences'),audit=S.ws.audit;if(!form||!audit)return;const chosen=$$('[name="advancedModules"]:checked',form).map(x=>x.value),moduleIds=new Set((audit.advancedModules||[]).map(m=>m.id));const changes=[];$$('select[name^="allocation:"]',form).forEach(select=>{for(const option of select.options)option.disabled=moduleIds.has(option.value)&&!chosen.includes(option.value);const id=select.name.slice(11),previous=audit.preferences?.allocations?.[id]||'';if(select.selectedOptions[0]?.disabled)select.value='';if(select.value!==previous){const label=select.closest('.allocation-row').dataset.courseLabel;changes.push(`${label}：${select.value?'改为 '+select.selectedOptions[0].textContent:'清除原手动分配，按当前路线核算'}`);}});$('#allocation-summary').innerHTML=changes.length?`<strong>保存后将更新 ${changes.length} 项归属：</strong><br>${changes.map(html).join('<br>')}`:'归属修改将在保存培养选择后生效。';}

function showGroupMembers(index){const view=S.analytics?.views?.[S.view],group=view?.groups?.[index];if(!group)return;S.ws.memberGroup=group;layer(`${html(view.name)} · ${html(group.name)}`,`<p class="small muted space-b">当前组共 ${group.students?.length||0} 位学生，可搜索并查看任意一位的画像。</p><label class="search" style="display:block;margin-bottom:17px">${ico('search')}<input id="group-member-query" class="field" placeholder="搜索姓名 / 学号" aria-label="搜索本组学生"></label><div id="group-member-list">${groupMemberRows(group.students||[])}</div>`);}
function groupMemberRows(students){return students.map(s=>`<div class="row">${person(s.name,s.id)}<button class="btn link" data-action="profile" data-id="${html(s.id)}">查看画像 ${ico('next')}</button></div>`).join('')||empty('没有符合条件的学生');}
function filterGroupMembers(query){const needle=query.toLowerCase();$('#group-member-list').innerHTML=groupMemberRows((S.ws.memberGroup?.students||[]).filter(s=>`${s.name} ${s.id}`.toLowerCase().includes(needle)));}

const forecastMetricLabels={auc:'ROC-AUC',rocAuc:'ROC-AUC',roc_auc:'ROC-AUC',prAuc:'PR-AUC',average_precision:'平均精确率',accuracy:'准确率',balancedAccuracy:'平衡准确率',precision:'精确率',recall:'召回率',f1:'F1',brier:'Brier 误差',brierScore:'Brier 误差',brier_score:'Brier 误差'};
function forecastEvaluation(data){const e=data.evaluation||{},m=e.metrics||{},b=e.baseline?.metrics||e.baseline||{},keys=Object.keys(m).filter(k=>forecastMetricLabels[k]&&(typeof m[k]==='number'||m[k]==null));return `<div class="forecast-evaluation"><div class="tags"><span class="tag">训练：${e.trainSamples??'—'} 条 / ${e.trainStudents??'—'} 人</span><span class="tag">测试：${e.testSamples??'—'} 条 / ${e.testStudents??'—'} 人</span>${e.cutoff?`<span class="tag">时间分界 ${html(e.cutoff)}</span>`:''}</div>${keys.length?`<div class="table-scroll"><table><thead><tr><th>留出评估指标</th><th>${html(typeof data.model==='string'?data.model:'逻辑回归模型')}</th><th>${html(e.baseline?.name||e.baselineName||'基线')}</th></tr></thead><tbody>${keys.map(k=>`<tr><td>${forecastMetricLabels[k]}</td><td>${m[k]==null?'不可计算':number(m[k],3)}</td><td>${typeof b[k]==='number'?number(b[k],3):'未提供'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="source">当前评估未返回可展示的对照指标。</p>'}</div>`;}
function forecastRows(items){return items.map(item=>`<details class="forecast-student"><summary><span>${person(item.name,item.studentId)}</span><span class="small muted">${html(item.featureTerm)} → ${html(item.targetTerm)}</span><strong>${number(item.score,3)}</strong></summary><div class="forecast-details"><p class="source">辅助风险得分，不作为正式预警等级或经过校准的概率承诺。下列数值解释本次模型评分。</p><div class="table-scroll"><table><thead><tr><th>影响因素</th><th>当前值</th><th>模型贡献</th></tr></thead><tbody>${(item.factors||[]).map(f=>`<tr><td>${html(f.name)}</td><td>${typeof f.value==='number'?number(f.value,3):html(f.value)}</td><td>${typeof f.contribution==='number'?(f.contribution>0?'+':'')+number(f.contribution,3):'—'}</td></tr>`).join('')}</tbody></table></div>${(item.notes||[]).map(n=>`<p class="source">${html(n)}</p>`).join('')}<button class="btn link" data-action="profile" data-id="${html(item.studentId)}">结合完整学情判断 ${ico('next')}</button></div></details>`).join('')||empty('没有可展示的预测结果');}
function drawForecast(){if(!$('#forecast-students'))return;const all=S.ws.forecast?.items||[],query=(S.ws.forecastQuery||'').toLowerCase(),items=all.filter(s=>`${s.name} ${s.studentId}`.toLowerCase().includes(query));const pages=Math.max(1,Math.ceil(items.length/10));S.ws.forecastPage=Math.max(1,Math.min(S.ws.forecastPage||1,pages));$('#forecast-students').innerHTML=forecastRows(items.slice((S.ws.forecastPage-1)*10,S.ws.forecastPage*10));$('#forecast-pagination').innerHTML=`<span>共 ${items.length} 人 · 每页 10 人</span><div class="pagination"><button data-action="forecast-prev" ${S.ws.forecastPage===1?'disabled':''} aria-label="上一页预测">‹</button><span>${S.ws.forecastPage}</span> / ${pages}<button data-action="forecast-next" ${S.ws.forecastPage===pages?'disabled':''} aria-label="下一页预测">›</button></div>`;}
async function loadForecast(ticket){const panel=$('#forecast-panel');if(!panel)return;panel.innerHTML=card('下一学期风险辅助观察','<div class="loading-line"><i class="loading-dot"></i>读取模型与留出评估结果…</div>','与公开规则预警分开呈现');try{const d=await request('/api/analytics/forecast');if(ticket!==S.ticket||!$('#forecast-panel'))return;S.ws.forecast=d;S.ws.forecastPage=1;S.ws.forecastQuery='';const simulated=d.isDemo??d.demo??S.status.demo??S.demo;panel.innerHTML=card('下一学期风险辅助观察',`<div class="tip space-b">${simulated?'当前为模拟数据评估，用来验证功能与比较基线；不代表真实学生预测效果。':'以已观察到的后续结果作留出评估，实际使用仍需持续验证。'}辅助模型不会提高或取消任何正式预警。</div>${d.available?`<p class="small space-b">预测目标：${html(textValue(d.target))}</p>${forecastEvaluation(d)}<div class="section-top" style="margin:23px 0 14px"><h3>学生辅助评分与影响因素</h3><label class="search">${ico('search')}<input class="field" id="forecast-query" placeholder="搜索姓名 / 学号" aria-label="搜索辅助评分学生"></label></div><div id="forecast-students"></div><div id="forecast-pagination" class="table-bottom"></div>`:`<div class="empty">${html(d.reason||'当前样本或历史覆盖不足，暂不展示辅助预测。')}</div>`}${(d.limitations||[]).map(n=>`<p class="source">${html(n)}</p>`).join('')}`,simulated?'模拟数据 · 学生与时间分离的留出评估':'辅助模型 · 独立留出评估');if(d.available)drawForecast();}catch(e){if(ticket===S.ticket&&$('#forecast-panel'))panel.innerHTML=card('下一学期风险辅助观察',`<p class="small muted">当前辅助预测暂不可用：${html(e.message)}</p>`,'群体画像与规则预警仍可正常查看');}}
function inlineFailure(error){return `<div class="error"><h2>这一步暂时没有完成</h2><p>${html(error.message||error)}</p><p class="small" style="margin-top:10px">已保存的数据不受影响。请稍后重试。</p></div>`;}
function configureMobileNavigation(){if(!S.ws.navMedia){S.ws.navMedia=window.matchMedia('(max-width: 760px)');S.ws.navMedia.addEventListener('change',()=>setMobileNavigation(false,false));}const frame=$('.app-frame');if(frame&&!$('.nav-backdrop')){const backdrop=document.createElement('button');backdrop.type='button';backdrop.className='nav-backdrop';backdrop.dataset.action='mobile-nav-close';backdrop.setAttribute('aria-label','关闭导航');backdrop.hidden=true;frame.prepend(backdrop);}setMobileNavigation(false,false);}
function setMobileNavigation(open,restoreFocus=false){const rail=$('.rail'),frame=$('.app-frame'),main=$('.main-area'),burger=$('.mobile-menu'),backdrop=$('.nav-backdrop');if(!rail||!frame)return;const mobile=S.ws.navMedia?.matches??window.matchMedia('(max-width: 760px)').matches;const visible=mobile&&open;frame.classList.toggle('menu-open',visible);rail.inert=mobile&&!visible;if(mobile&&!visible)rail.setAttribute('aria-hidden','true');else rail.removeAttribute('aria-hidden');if(main)main.inert=visible;if(burger)burger.setAttribute('aria-expanded',String(visible));if(backdrop)backdrop.hidden=!visible;if(visible){document.body.style.overflow='hidden';$('.nav-item',rail)?.focus();}else{if(!$('#layer .backdrop'))document.body.style.overflow='';if(restoreFocus&&mobile&&burger){burger.disabled=false;burger.focus();}}}
document.addEventListener('keydown',e=>{const frame=$('.app-frame');if(!frame?.classList.contains('menu-open')||$('#layer .backdrop'))return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();setMobileNavigation(false,true);return;}if(e.key==='Tab'){const items=$$('button:not(:disabled),a[href],input,select,textarea',$('.rail')).filter(el=>!el.hidden&&el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}},true);
function sessionState(){if(S.ws.account===S.user?.id)return;Object.assign(S.ws,{account:S.user?.id,threadId:null,threads:[],messages:[],chatContext:null,chatBusy:false,chatDraft:'',planning:null,audit:null,selection:[],planningCheck:null,planStudent:null,planTerm:null,planDrafts:{},taskFilter:'active'});S.messages=[];S.query='';S.level='';S.major=S.user?.id?.includes('SE')?'SE':'CS';}
async function go(page){sessionState();S.page=page;const ticket=++S.ticket;close();setMobileNavigation(false,false);$$('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));$('#crumb').textContent=$(`[data-page="${page}"] span`)?.textContent||({planner:'学期选课规划',submissions:'学生选课方案'}[page])||'知学';$('#page').innerHTML='<div class="skeleton short"></div><div class="skeleton"></div><div class="skeleton"></div>';try{const views={overview,students,ledger,analytics,curriculum,assistant,mine,credits,myalerts,plan,settings,planner,submissions};const content=await(views[page]||overview)();if(ticket!==S.ticket)return;$('#page').innerHTML=content+footer();if(page==='overview')drawQueue();if(page==='credits'){S.coursePage=1;drawCourses();}if(page==='assistant')scrollChat();if(page==='planner')renderOfferings();if(page==='analytics')loadForecast(ticket);if(S.user.role!=='student'&&page==='overview')loadOverviewExtras(ticket);}catch(e){if(ticket===S.ticket)$('#page').innerHTML=inlineFailure(e)+btn('重新载入','refresh','refresh');}}
function close(){stashFollowupDraft();S.ws.overlayTicket++;const trigger=S.lastFocus;$('#layer').innerHTML='';document.body.style.overflow='';if(trigger?.isConnected)trigger.focus();}
function layer(title,content,modal=false){stashFollowupDraft();if($('.app-frame')?.classList.contains('menu-open'))setMobileNavigation(false,true);S.ws.overlayTicket++;S.lastFocus=document.activeElement;$('#layer').innerHTML=`<div class="backdrop"><section class="${modal?'modal':'drawer'}" role="dialog" aria-modal="true" aria-label="${html(title)}"><header class="drawer-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭面板">${ico('close')}</button></header><div class="drawer-body">${content}</div></section></div>`;document.body.style.overflow='hidden';$('#layer button')?.focus();return S.ws.overlayTicket;}
async function openProfile(id){const token=layer('学生学情与支持计划','<div class="skeleton"></div>');try{const [p,tasks]=await Promise.all([request(apiStudent(id)),request(apiStudent(id)+'/plan')]);if(token!==S.ws.overlayTicket)return;p.studyTasks=tasks.tasks||[];S.profile=p;S.major=p.student.major||S.major;$('.drawer-body').innerHTML=`<div class="button-row space-b"><button class="btn" data-action="open-planner" data-student="${html(id)}">${ico('curriculum')}查看学期选课方案</button>${S.user.role!=='student'?`<button class="btn" data-action="assign-task" data-student="${html(id)}">${ico('check')}安排学习行动</button>`:''}</div>`+profileContent(p);S.coursePage=1;drawCourses();}catch(e){if(token===S.ws.overlayTicket)$('.drawer-body').innerHTML=inlineFailure(e);}}
async function openAlert(id){const token=layer('预警解释与帮扶记录','<div class="skeleton"></div>');try{const d=await request('/api/alerts/'+encodeURIComponent(id));if(token!==S.ws.overlayTicket)return;S.alertDetail=d;$('.drawer-body').innerHTML=alertContent(d)+`<div class="button-row"><button class="btn" data-action="open-planner" data-student="${html(d.alert.studentId)}">${ico('curriculum')}结合选课方案跟进</button>${S.user.role!=='student'?`<button class="btn" data-action="assign-task" data-student="${html(d.alert.studentId)}" data-alert="${html(id)}">${ico('check')}安排一项学习行动</button>`:''}</div>`;const previous=[...(d.events||[])].reverse().find(e=>e.plan||e.reviewOn);if(previous&&$('#followup')){if(previous.plan)$('#followup [name="plan"]').value=previous.plan;if(previous.reviewOn)$('#followup [name="reviewOn"]').value=previous.reviewOn;}restoreFollowupDraft();}catch(e){if(token===S.ws.overlayTicket)$('.drawer-body').innerHTML=inlineFailure(e);}}
async function loadOverviewExtras(ticket){try{const [plans,notices]=await Promise.all([request('/api/counselor/plans'),request('/api/notifications')]);if(ticket!==S.ticket||S.page!=='overview')return;const pending=plans.items.filter(p=>p.status==='submitted');const unread=notices.items.filter(n=>!n.read);const slot=document.createElement('div');slot.className='queue-filter-row space-b';slot.innerHTML=`<button class="btn" data-page="submissions">${ico('curriculum')}待查看选课方案 <strong>${pending.length}</strong></button><button class="btn" data-action="notifications">${ico('bell')}未读反馈与通知 <strong>${notices.unread}</strong>${unread.length?'<i class="unread-dot"></i>':''}</button>`;$('.dashboard-grid')?.before(slot);}catch{/* The core overview remains usable if optional summaries fail. */}}

// Persistent conversations and reviewable proposals.
function rememberThread(){try{if(S.ws.threadId)localStorage.setItem('zhixue.thread.'+S.user.id,S.ws.threadId);else localStorage.removeItem('zhixue.thread.'+S.user.id);}catch{}}
async function loadThreads(){const data=await request('/api/assistant/threads');S.ws.threads=data.items||[];return S.ws.threads;}
async function loadConversation(id,ticket=null){const owner=S.user.id;const d=await request('/api/assistant/threads/'+encodeURIComponent(id));if(S.user?.id!==owner||(ticket!==null&&ticket!==S.ws.conversationTicket))return null;S.ws.threadId=d.id;S.ws.chatContext=d.studentId||null;S.ws.messages=d.messages||[];rememberThread();return d;}
function threadRail(){return `<aside class="conversation-rail"><div class="conversation-rail-head"><button class="btn" data-action="new-thread">${ico('assistant')}开始新对话</button></div><div class="conversation-rail-label">最近的对话</div><div class="thread-list">${S.ws.threads.map(t=>`<button class="thread-item ${t.id===S.ws.threadId?'selected':''}" data-action="thread" data-id="${html(t.id)}"><strong>${html(t.title||'学情咨询')}</strong><small>${t.studentId?html(t.studentId)+' · ':''}${date(t.updatedAt)}</small></button>`).join('')||'<p class="source" style="padding:10px">对话会自动保存在这里。</p>'}</div></aside>`;}
function sourceMarkup(m){const refs=m.citations||[];if(refs.length)return `<div class="message-sources">参考依据　${refs.map(c=>{const link=safeLink(c.url);const label=`${c.id?html(c.id)+' · ':''}${html(c.title||'数据来源')}${c.page?' · 第 '+html(c.page)+' 页':''}`;return link?`<a class="source-chip" href="${html(link)}" target="_blank" rel="noopener">${label} ↗</a>`:`<span class="source-chip">${label}</span>`;}).join('')}</div>`;return m.sources?.length?`<div class="message-sources">依据：${m.sources.map(x=>html(textValue(x))).join('；')}</div>`:'';}
function proposalMarkup(p){const applied=p.status==='applied';return `<article class="proposal-card" data-proposal="${html(p.id)}"><div class="proposal-heading"><small>可采纳的行动草案${p.studentId?' · '+html(p.studentId):''}</small><h3>${html(p.title)}</h3></div><div class="proposal-body"><p>${html(p.summary||'请核对具体行动与时间安排，再决定是否采纳。')}</p>${(p.items||[]).map(x=>`<div class="proposal-item"><strong>${html(x.title)}</strong>${x.description?`<p>${html(x.description)}</p>`:''}<small>${x.dueDate?'计划完成：'+html(x.dueDate):'未设置截止日期'}</small></div>`).join('')}</div><div class="proposal-footer"><small>${applied?'已添加至学生行动计划。同一草案不会重复添加。':'核对后点击采纳，才会添加到学生行动计划。'}</small><button class="btn ${applied?'':'primary'}" data-action="apply-proposal" data-id="${html(p.id)}" ${applied?'disabled':''}>${ico('check')}${applied?'已采纳':'采纳这份计划'}</button></div></article>`;}
function conversationMessage(m){const user=m.role==='user';const steps=m.steps||[];return `<article class="message ${user?'user':''}"><span class="avatar">${user?'我':'知'}</span><div class="message-content">${!user&&steps.length?`<details class="tool-trace"><summary>${ico('check')}已完成 ${steps.length} 项数据核对</summary><div class="tool-steps">${steps.map(s=>`<div class="tool-step"><strong>${s.status==='error'?'未完成 · ':''}${html(s.label||'学情查询')}</strong>${s.summary?`<p>${html(textValue(s.summary))}</p>`:''}</div>`).join('')}</div></details>`:''}<div class="bubble">${html(m.content??m.text??'')}</div>${!user?sourceMarkup(m):''}${(m.warnings||[]).map(w=>`<div class="chat-warning">${html(w)}</div>`).join('')}${(m.proposals||[]).map(proposalMarkup).join('')}<div class="message-time">${m.createdAt?date(m.createdAt):user?'刚刚':''}${m.mode&&!user?' · '+(m.mode==='remote'?'大模型辅助':'本地学情工作流'):''}</div></div></article>`;}
function chatStarters(){const items=S.user.role==='student'?[['curriculum','核对我的培养要求','我的个性化路径和进阶模块还差哪些要求？'],['analytics','安排下学期选课','请结合我的学情，推荐下学期的选课组合。'],['alert','解释当前预警','我的预警是怎么触发的？最先应该处理什么？'],['check','生成可执行计划','请根据我的学情生成一份可采纳的学习行动计划。']]:[['students','确定优先关注对象','当前应该优先关注哪些学生？请说明原因。'],['curriculum','查看选课规划','帮我检查当前学生的学分缺口和下学期选课方案。'],['ledger','回顾跟进进展','请总结当前学生的帮扶记录和接下来需要复查的事项。'],['check','拟定帮扶行动','请为当前学生生成一份可采纳的学习行动草案。']];return `<div class="chat-starters">${items.map(([i,t,q])=>`<button class="chat-starter" data-action="ask" data-question="${html(q)}">${ico(i)}<strong>${t}</strong><small>${html(q)}</small></button>`).join('')}</div>`;}
function chatBody(){return `${S.ws.messages.length?`<div class="chat-messages" id="chat-log" aria-live="polite">${S.ws.messages.map(conversationMessage).join('')}${S.ws.chatBusy?'<div class="loading-line"><i class="loading-dot"></i>知学正在查询数据并整理回答…</div>':''}</div>`:`<div class="chat-messages" id="chat-log" style="min-height:145px;max-height:none"><div class="message"><span class="avatar">知</span><div class="message-content"><div class="bubble">${S.user.role==='student'?'你好，我会结合你的专业、培养方案与学习进度，陪你理清下一步。可以从一个具体问题开始。':'你好，我可以结合学生画像、课程方案与帮扶记录，协助你判断需要关注的事项。查询具体学生时，可以先告诉我姓名或学号。'}</div></div></div></div>${chatStarters()}`}<form class="chat-input" id="conversation-form"><textarea name="message" aria-label="给知学的问题" maxlength="2000" placeholder="继续提问，知学会记住本次对话的上下文…" required ${S.ws.chatBusy?'disabled':''}>${html(S.ws.chatDraft)}</textarea><button class="btn primary" type="submit" ${S.ws.chatBusy?'disabled':''}>${ico('send')}${S.ws.chatBusy?'处理中':'发送'}</button></form><div class="chat-disclaimer">${S.status.ai?.configured&&S.status.ai.mode==='remote'?'模型结合实际查询结果回答；涉及修改的行动草案需你确认。':'当前为本地学情工作流，可核对数据、解释规则、生成行动草案。'} 对话与结果按当前账号权限保存。</div>`;}
async function assistant(){const user=S.user.id;await loadThreads();if(user!==S.user.id)return '';if(!S.ws.threadId&&!S.ws.forceNew){let remembered;try{remembered=localStorage.getItem('zhixue.thread.'+user);}catch{}if(S.ws.threads.some(t=>t.id===remembered))await loadConversation(remembered);}S.ws.forceNew=false;return heading('知学助手','带着专业背景与学习上下文，把问题一步步聊清楚。')+`<div class="conversation-layout">${threadRail()}<section class="card conversation-main"><div class="card-head"><div><h2>${ico('assistant')}　一起找到下一步</h2><p class="conversation-context">${S.ws.chatContext?'当前学生：'+html(S.ws.chatContext):S.user.role==='student'?html(S.user.name)+'的学业咨询':'可查询当前权限范围内的学生'}</p></div><span class="badge">${S.status.ai?.configured&&S.status.ai.mode==='remote'?'大模型已接入':'本地工作流'}</span></div><div id="conversation-body">${chatBody()}</div></section></div>`;}
function renderConversation(){const context=$('.conversation-context');if(context)context.textContent=S.ws.chatContext?'当前学生：'+S.ws.chatContext:(S.user.role==='student'?S.user.name+'的学业咨询':'可查询当前权限范围内的学生');const body=$('#conversation-body');if(body){body.innerHTML=chatBody();scrollChat();}const rail=$('.conversation-rail');if(rail)rail.outerHTML=threadRail();}
async function ask(message,studentId){sessionState();if(S.ws.chatBusy){toast('知学正在完成上一条查询');return;}if(studentId&&studentId!==S.ws.chatContext){S.ws.threadId=null;S.ws.messages=[];S.ws.chatContext=studentId;S.ws.forceNew=true;rememberThread();}if(S.page!=='assistant')await go('assistant');const accountId=S.user.id,context=S.ws.chatContext;S.ws.chatBusy=true;S.ws.chatDraft='';S.ws.messages.push({role:'user',content:message,createdAt:new Date().toISOString()});renderConversation();try{const d=await request('/api/assistant',{method:'POST',body:JSON.stringify({message,...(S.ws.threadId?{threadId:S.ws.threadId}:{}),...(!S.ws.threadId&&context?{studentId:context}:{})})});if(S.user?.id!==accountId)return;S.ws.threadId=d.threadId||S.ws.threadId;if(Object.prototype.hasOwnProperty.call(d,'studentId'))S.ws.chatContext=d.studentId||null;S.ws.messages.push({id:d.messageId,role:'assistant',content:d.answer,mode:d.mode,steps:d.steps,sources:d.sources,citations:d.citations,warnings:d.warnings,proposals:d.proposals,createdAt:new Date().toISOString()});rememberThread();try{await loadThreads();}catch{} }catch(e){if(S.user?.id!==accountId)return;S.ws.chatDraft=message;S.ws.messages.push({role:'assistant',content:'这次查询没有完成：'+e.message,warnings:['你的问题已保留在输入框，可在服务恢复后重试。']});}finally{if(S.user?.id===accountId){S.ws.chatBusy=false;if(S.page==='assistant')renderConversation();}}}

// Curriculum audit and elective paths.
function auditCheckList(checks){return `<ul class="check-list">${(checks||[]).map(c=>`<li class="${c.met?'':'unmet'}">${checkIcon(c.met)}<div><strong>${html(c.name)}</strong>${html(c.value??'待核对')} / ${html(c.target??'待确认')}${c.note?`<small>${html(c.note)}</small>`:''}${c.sourcePage?`<small>培养方案第 ${html(c.sourcePage)} 页</small>`:''}</div></li>`).join('')}</ul>`;}
function auditModule(m){return `<section class="module-audit"><div class="module-audit-top"><h3>${html(m.name)}</h3><span class="badge ${m.met?'':'level2'}">${m.met?'要求已满足':'仍需修读'}</span></div><div class="module-statline"><div>模块总分<strong>${number(m.earned,1)} / ${number(m.totalRequired,1)}</strong></div><div>限选部分<strong>${number(m.requiredEarned,1)} / ${number(m.requiredCredits,1)}</strong></div><div>任选部分<strong>${number(m.optionalEarned,1)} / ${number(m.optionalRequired,1)}</strong></div></div>${m.requiredMissing?.length?`<p class="module-missing">尚未完成的限选课程：${m.requiredMissing.map(c=>`${html(c.name)}（${c.credits} 分）`).join('、')}</p>`:''}<details class="tool-trace"><summary>查看课程核算明细</summary><div class="tool-steps">${(m.courses||[]).map(c=>`<div class="row"><div>${html(c.name)}<small>${c.requiredInModule?'限选':'任选'} · ${c.credits} 学分${c.allocatedTo&&c.allocatedTo!==m.id?' · 已计入其他模块':''}</small></div><span class="badge ${c.passed?'':'level2'}">${c.passed?'已通过':'未完成'}</span></div>`).join('')}</div></details><div class="audit-source-line">培养方案第 ${(m.sourcePages||[]).map(html).join('、')} 页</div></section>`;}
function preferencesForm(a,readOnly=false){const pref=a.preferences||{},selected=pref.advancedModules||[];const moduleNames=Object.fromEntries((a.advancedModules||[]).map(m=>[m.id,m.name]));return `<form id="curriculum-preferences" data-student="${html(a.studentId)}"><div class="preference-fields"><label class="form-item">外语学习路线<select name="language" ${readOnly?'disabled':''}>${(a.languages||[]).map(l=>`<option value="${html(l.id)}" ${l.id===pref.language?'selected':''}>${html(l.name)}${l.credits?' · '+l.credits+' 学分':''}</option>`).join('')}</select></label><label class="form-item">个性化培养路径<select name="path" ${readOnly?'disabled':''}>${(a.paths||[]).map(p=>`<option value="${html(p.id)}" ${p.id===pref.path?'selected':''}>${html(p.name)}</option>`).join('')}</select></label><div class="form-item preference-modules"><span>专业进阶模块</span><div class="choice-grid">${(a.advancedModules||[]).map(m=>`<label class="check-option"><input type="checkbox" name="advancedModules" value="${html(m.id)}" ${selected.includes(m.id)?'checked':''} ${readOnly?'disabled':''}><span>${html(m.name)}<small style="display:block">${m.credits} 学分</small></span></label>`).join('')}</div></div></div><div class="module-path-summary">${html((a.paths||[]).find(p=>p.id===pref.path)?.description||'按所选路径核对进阶模块与个性化学分。')}</div>${allocationManager(a,readOnly)}${readOnly?'<p class="source">培养路径由学生本人选择，辅导员可查看并提出建议。</p>':`<div class="form-actions"><button class="btn primary" type="submit">${ico('check')}保存选择并重新核对</button></div>`}<div class="form-error"></div></form>`;}
async function credits(){const id=S.user.id;const [p,a]=await Promise.all([request(apiStudent(id)),request(apiStudent(id)+'/curriculum-audit')]);S.profile=p;S.ws.audit=a;const selected=(a.moduleAudits||[]).filter(m=>m.selected);return heading('我的培养要求','选清楚学习路线，再逐项核对自己的课程与学分。',`<button class="btn primary" data-action="open-planner" data-student="${html(id)}">${ico('analytics')}打开选课规划</button>`)+`${dataNotes(p)}<div class="stats">${stat('毕业要求',p.credits.total,'学分',html(p.student.majorName),'curriculum')}${stat('已获得',number(p.credits.earned,1),'学分','通过课程去重后累计','check')}${stat('还需完成',number(p.credits.remaining,1),'学分','结合分模块要求一起核对','ledger','gold')}${stat('当前学期',p.credits.semester||'—','',a.preferences?.isDefault?'建议先确认自己的培养路径':'已采用你保存的培养选择','clock','blue')}</div><div class="audit-intro space-b">${card('我的培养路线',preferencesForm(a),'外语、个性化路径与进阶模块，都将用于后续选课检查')}${card('学分与专项要求',creditBars({categories:a.categories||[]})+auditCheckList(a.checks),'核对培养方案明确规定的总分与专项要求')}</div><div class="grid2 space-b">${card('专业进阶模块',selected.length?selected.map(auditModule).join(''):'<div class="tip warn">尚未选择专业进阶模块。请先确认上方培养路线，再核对模块内的限选和任选课程。</div>','共享课程按单一归属计算，避免学分重复计入')}${card('个性化路径核对',`<div class="tip ${a.pathAudit?.status==='met'?'':'warn'}"><strong>${html(a.pathAudit?.name||'待确认路径')}</strong><br>${a.pathAudit?.status==='met'?'当前已满足所选路径要求。':a.pathAudit?.status==='needs_confirmation'?'部分课程认定仍需确认，请结合培养方案原件与学院认定结果核对。':'还有要求尚未完成，可在下面查看具体差距。'}</div>${auditCheckList(a.pathAudit?.checks)}${(a.pathAudit?.notes||[]).map(n=>`<p class="source">${html(n)}</p>`).join('')}`,'把“总学分够了”和“培养要求完成了”一起核对')}</div>${card('课程修读清单',`<div class="offering-filters"><label class="search">${ico('search')}<input class="field" id="profile-course-query" placeholder="课程名称 / 课程代码" aria-label="搜索课程"></label><select id="profile-course-filter" aria-label="修读状态"><option value="">全部课程</option><option value="failed">未通过</option><option value="enrolled">待出分</option><option value="passed">已通过</option><option value="remaining">尚未修读</option></select></div><div class="table-scroll"><table><thead><tr><th>课程</th><th>学分</th><th>成绩</th><th>修读状态</th></tr></thead><tbody id="profile-course-list"></tbody></table></div><div id="course-pager" class="table-bottom"></div>`,'成绩未发布时保留“待出分”，不会当作挂科')}<p class="source">${(a.sources||[]).map(x=>typeof x==='string'?html(x):html(x.title)+(x.page?' · 第 '+html(x.page)+' 页':'')).join('；')}</p>`;}

// Plan a course combination, check it, then deliberately save or submit it.
function selectedOfferings(){const ids=new Set(S.ws.selection);return (S.ws.planning?.offerings||[]).filter(o=>ids.has(o.courseId));}
function termChoices(selected){const values=new Set([selected,S.status.term]);let parts=String(S.status.term||selected).split('-').map(Number);for(let i=0;i<2;i++){parts=parts[2]===1?[parts[0],parts[1],2]:[parts[0]+1,parts[1]+1,1];values.add(parts.join('-'));}return [...values].filter(Boolean).sort().map(term=>`<option value="${html(term)}" ${term===selected?'selected':''}>${html(term)} 学期</option>`).join('');}
function stashPlanDraft(){const p=S.ws.planning;if(!p||S.user.role!=='student'||p.savedPlan?.status==='submitted')return;S.ws.planDirty=true;S.ws.planDrafts??={};S.ws.planDrafts[S.ws.planStudent+'|'+p.term]={dirty:true,courseIds:[...S.ws.selection],title:S.ws.planTitle,note:S.ws.planNote};}
function planningContext(p,student){return `<div class="planner-context"><span class="avatar">${html(student.name.slice(-2))}</span><div><strong>${html(student.name)} · ${html(student.majorName)}</strong><p>${html(student.id)}　${html(p.term)} 学期${p.dataMode==='demo'?' · 演示课表与先修条件':p.dataMode==='unavailable'?' · 暂无开课数据':''}</p></div><div class="actions"><label class="form-item"><span class="a11y-only">规划学期</span><select id="planning-term" aria-label="规划学期">${termChoices(p.term)}</select></label><button class="btn compact" data-action="ask" data-student="${html(student.id)}" data-question="请结合当前学情和培养要求，解释这位学生的选课重点。">${ico('assistant')}问问知学</button></div></div>`;}
function planReviewBanner(saved){if(!saved)return '';if(saved.status==='revision'||saved.status==='approved')return `<div class="review-banner ${saved.status==='approved'?'approved':''}"><strong>${html(planStatus[saved.status])} · ${html(saved.reviewerName||'负责辅导员')}</strong>${html(saved.reviewComment||'已查看本次方案。')}<div class="tiny" style="margin-top:5px">${date(saved.reviewedAt)}</div></div>`;return saved.status==='submitted'?'<div class="tip space-b">选课方案已提交。辅导员可以查看你的组合与检查结果，并给出建议。本次提交等待辅导员查看，暂时不能修改；收到调整意见后可以继续编辑。</div>':'';}
function offeringHTML(o,readOnly){const selected=S.ws.selection.includes(o.courseId);const reasons=o.reasons||[];const unmet=(o.prerequisites||[]).filter(p=>!p.met);return `<article class="offering-card ${selected?'selected':''}"><input class="course-check" type="checkbox" data-course="${html(o.courseId)}" aria-label="选择${html(o.name)}" ${selected?'checked':''} ${readOnly?'disabled':''}><div class="offering-main"><h3>${html(o.name)} ${o.passed?'<span class="badge">已通过</span>':''}</h3><div class="offering-meta"><span>${html(o.code)}</span><span>${html(o.category)}</span><span>${o.required?'必修':'选修'}</span>${o.semester?`<span>建议第 ${o.semester} 学期</span>`:''}</div><div class="offering-detail">${ico('clock')} ${html(o.scheduleText||'暂未公布上课时段')}<br>${o.prerequisites?.length?'先修：'+o.prerequisites.map(p=>html(p.name)+(p.met?' ✓':'（尚未满足）')).join('、'):'未设定先修要求'}</div>${reasons.length?`<div class="course-reason">${ico('assistant')}<span>${reasons.map(html).join('；')}</span></div>`:''}${unmet.length?'<span class="badge level2" style="margin-top:7px">需要先核对先修要求</span>':''}</div><div class="offering-side"><strong>${number(o.credits,1)}</strong><small> 学分</small><div class="availability ${o.seats<=0?'full':''}">${o.capacity!=null?'余位 '+Math.max(0,o.seats??0):'容量待确认'}</div></div></article>`;}
function renderOfferings(){if(!$('#offering-list'))return;const p=S.ws.planning,q=S.ws.offeringQuery.toLowerCase(),filter=S.ws.offeringFilter;const recommended=new Set(p.recommended?.courseIds||[]),readOnly=S.user.role!=='student'||S.ws.planning?.savedPlan?.status==='submitted';const rows=(p.offerings||[]).filter(o=>`${o.name} ${o.code}`.toLowerCase().includes(q)&&(filter==='all'||filter==='unfinished'&&!o.passed||filter==='recommended'&&recommended.has(o.courseId)||filter==='selected'&&S.ws.selection.includes(o.courseId)||filter==='required'&&o.required)).sort((a,b)=>Number(recommended.has(b.courseId))-Number(recommended.has(a.courseId))||Number(b.required)-Number(a.required)||a.semester-b.semester);const pages=Math.max(1,Math.ceil(rows.length/10));S.ws.offeringsPage=Math.min(S.ws.offeringsPage,pages);$('#offering-list').innerHTML=rows.slice((S.ws.offeringsPage-1)*10,S.ws.offeringsPage*10).map(o=>offeringHTML(o,readOnly)).join('')||empty('没有符合条件的开课记录');$('#offering-pagination').innerHTML=`<span>共 ${rows.length} 门 · 每页 10 门</span><div class="pagination"><button data-action="offer-prev" ${S.ws.offeringsPage===1?'disabled':''} aria-label="课程上一页">‹</button><span>${S.ws.offeringsPage}</span> / ${pages}<button data-action="offer-next" ${S.ws.offeringsPage===pages?'disabled':''} aria-label="课程下一页">›</button></div>`;}
function checkMarkup(c){if(!c)return '<p class="source">调整课程组合后，点击“检查这个组合”，查看时间、先修、容量与修读学期是否合适。</p>';return `${c.missingRequired?.length?`<div class="tip warn space-b">还有 ${c.missingRequired.length} 门必修课程待核对。当前组合可用于讨论，不表示已完成整个学期安排。</div>`:''}${c.eligible?`<div class="check-success">${ico('check')} 暂未发现阻止提交的问题。${c.conflicts?.length?'还有提醒项，请阅读后决定。':'当前所选课程没有已知阻断冲突。'}</div>`:'<div class="tip warn">组合存在需要解决的问题。可以先保存草案，调整后再提交给辅导员。</div>'}<div class="conflict-list">${(c.conflicts||[]).map(x=>`<div class="conflict-item ${x.level==='error'?'blocking':''}">${html(x.message)}${x.source?`<small>依据：${html(x.source)}</small>`:''}</div>`).join('')}</div>${(c.notes||[]).map(n=>`<p class="source">${html(n)}</p>`).join('')}`;}
function selectionSummary(){const p=S.ws.planning,saved=p.savedPlan,offerings=selectedOfferings(),total=offerings.reduce((n,c)=>n+c.credits,0),readOnly=S.user.role!=='student'||S.ws.planning?.savedPlan?.status==='submitted';return `<div class="planner-total"><strong>${number(total,1)}</strong><span>学分 · ${S.ws.selection.length} 门课程</span></div><div class="selection-list">${offerings.map(c=>`<div class="selection-row"><div>${html(c.name)}<small style="display:block">${number(c.credits,1)} 学分</small></div>${!readOnly?`<button class="icon-btn" data-action="remove-course" data-id="${html(c.courseId)}" aria-label="移除${html(c.name)}">${ico('close')}</button>`:''}</div>`).join('')||'<p class="source">勾选左侧课程，或者先采用推荐组合作为起点。</p>'}</div><div class="planner-stack">${readOnly&&saved?`<div class="tip"><strong>${html(saved.title)}</strong><p style="white-space:pre-wrap;margin-top:7px">${html(saved.note||'未填写选课说明')}</p></div>`:''}${!readOnly?`<label class="form-item">方案名称<input class="field" id="plan-title" maxlength="120" value="${html(S.ws.planTitle??saved?.title??'我的学期选课方案')}"></label><label class="form-item">我的考虑<textarea id="plan-note" maxlength="1500" placeholder="例如：先补齐必修课程，同时保留时间完成进阶模块。">${html(S.ws.planNote??saved?.note??'')}</textarea></label>`:''}<button class="btn" data-action="check-plan">${ico('check')}检查这个组合</button>${!readOnly?`<button class="btn" data-action="save-plan">${ico('file')}保存方案草案</button><button class="btn primary" data-action="submit-plan">${ico('send')}提交辅导员查看</button><small>这是学习规划，不会直接写入教务选课。</small>`:''}</div>${S.ws.planDirty?'<div class="saved-status">当前有未保存的调整</div>':saved?`<div class="saved-status">${ico('check')}${html(planStatus[saved.status]||saved.status)} · ${date(saved.updatedAt)}</div>`:''}`;}
function reviewForm(saved,id,term){if(S.user.role==='student'||!saved||saved.status!=='submitted')return '';return card('辅导员审核意见',`<form id="plan-review" data-student="${html(id)}" data-term="${html(term)}"><div class="form-grid"><label class="form-item">审核结果<select name="status"><option value="revision">建议调整后再次提交</option><option value="approved">认可当前规划</option></select></label><label class="form-item full">给学生的具体意见<textarea name="comment" required maxlength="2000" placeholder="指出需要调整的课程、原因和可行替代选择。">${html(saved.reviewComment||'')}</textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">${ico('send')}反馈给学生</button></div><div class="form-error"></div></form>`,'反馈将保存在方案中，并通知学生');}
function planEvents(saved){return (saved?.events||[]).slice().reverse().map(e=>`<div class="event"><small>${date(e.createdAt)} · ${html(e.actor)}</small><strong>${html(({saved:'保存了方案',submitted:'提交辅导员查看',approved:'认可了当前方案',revision:'建议调整方案',owner_changed:'变更负责辅导员'})[e.action]||e.action)}</strong>${e.payload?.title?`<p>${html(e.payload.title)}</p>`:''}${e.payload?.note?`<p>${html(e.payload.note)}</p>`:''}${e.payload?.comment?`<p>${html(e.payload.comment)}</p>`:''}${e.payload?.courseIds?`<p>本次记录包含 ${e.payload.courseIds.length} 门课程</p>`:''}</div>`).join('')||empty('保存或提交后，会记录方案变化。');}
function reviewPlanningPage(p,student){const saved=p.savedPlan;const courses=saved?.check?.courses||[];return heading('学生选课方案审核','先理解学生的安排，再针对课程组合给出具体反馈。',`<button class="btn" data-page="submissions">${ico('ledger')}返回方案列表</button><button class="btn" data-action="planner-audit">${ico('curriculum')}核对培养要求</button>`)+planningContext(p,student)+planReviewBanner(saved)+(saved?`<section class="card space-b"><div class="card-head"><div><h2>${html(saved.title||'学期选课方案')}</h2><p>${html(p.term)} · 第 ${saved.version} 版 · ${html(planStatus[saved.status])}</p></div><span class="badge">${courses.length} 门 / ${number(saved.check?.totalCredits||0,1)} 学分</span></div><div class="card-body"><h3 style="margin-bottom:9px">学生的考虑</h3><p class="small" style="white-space:pre-wrap;line-height:1.9">${html(saved.note||'学生尚未补充选课考虑，可以在审核意见中请同学说明。')}</p></div></section><div class="grid2 review-columns"><div>${card('学生选择的课程',`<div class="table-scroll"><table><thead><tr><th>课程</th><th>学分</th><th>上课安排</th></tr></thead><tbody>${courses.map(c=>`<tr><td>${html(c.name)}<small style="display:block" class="muted">${html(c.category)} · ${c.required?'必修':'选修'}</small></td><td>${number(c.credits,1)}</td><td style="white-space:normal;min-width:130px">${html(c.scheduleText||'待确认')}</td></tr>`).join('')}</tbody></table></div>`,'按本次已保存的课程组合核对')}${card('组合检查',`<div id="plan-check-result">${checkMarkup(saved.check)}</div>`,'检查不代替教务选课和最终修读认定')}</div><aside>${reviewForm(saved,student.id,p.term)||card('本轮反馈',`<div class="tip">${html(saved.reviewComment||'这份方案尚未提交，当前可先查看内容。学生提交后，可以在此给出审核意见。')}</div>`,saved.reviewerName?html(saved.reviewerName)+' · '+date(saved.reviewedAt):'等待下一步进展')}${card('方案与审核记录',planEvents(saved),'保留每次保存、提交与反馈')}</aside></div>`:card('学生尚未保存方案','<div class="tip">可以先查看培养要求并与学生讨论。学生保存、提交方案后，会在这里显示课程组合与说明。</div>'))+`<details class="tool-trace" style="margin-top:22px"><summary>展开参考开课目录（${p.offerings.length} 门）</summary><div class="tool-steps"><div class="offering-filters"><label class="search">${ico('search')}<input class="field" id="offering-query" placeholder="搜索开课课程"></label><select id="offering-filter" aria-label="参考课程筛选">${[['selected','本次组合'],['unfinished','未完成课程'],['recommended','推荐课程'],['all','全部开课']].map(([value,label])=>`<option value="${value}" ${value===S.ws.offeringFilter?'selected':''}>${label}</option>`).join('')}</select></div><div id="offering-list"></div><div id="offering-pagination" class="table-bottom"></div></div></details>`;}
async function planner(){const id=S.user.role==='student'?S.user.id:S.ws.planStudent;if(!id)return heading('学期选课规划','先从学生画像或已提交方案中选择一位同学。')+`<div class="tip">${btn('查看学生名单','students-page','students')}</div>`;const ticket=S.ticket,query=S.ws.planTerm?'?term='+encodeURIComponent(S.ws.planTerm):'';const [p,profile,audit]=await Promise.all([request(apiStudent(id)+'/planning'+query),request(apiStudent(id)),request(apiStudent(id)+'/curriculum-audit')]);if(ticket!==S.ticket)return '';S.ws.planning=p;S.ws.audit=audit;S.major=profile.student.major||S.major;S.ws.planStudent=id;const draft=(S.ws.planDrafts||{})[id+'|'+p.term];S.ws.selection=[...(draft?.dirty&&p.savedPlan?.status!=='submitted'?draft.courseIds:(p.savedPlan?.courseIds||[]))];S.ws.planDirty=Boolean(draft?.dirty);S.ws.planningCheck=draft?.dirty?null:(p.savedPlan?.check||null);S.ws.planTitle=draft?.dirty?draft.title:(p.savedPlan?.title||'我的学期选课方案');S.ws.planNote=draft?.dirty?draft.note:(p.savedPlan?.note||'');S.ws.offeringQuery='';S.ws.offeringFilter=p.savedPlan?.status==='submitted'?'selected':'unfinished';S.ws.offeringsPage=1;const readOnly=S.user.role!=='student'||S.ws.planning?.savedPlan?.status==='submitted';if(S.user.role!=='student')return reviewPlanningPage(p,profile.student);return heading(S.user.role==='student'?'我的学期选课规划':'学生选课方案','先看要求，再选组合；检查清楚后，与辅导员一起确认。',`<button class="btn" data-action="planner-audit">${ico('curriculum')}查看培养要求</button>`)+planningContext(p,profile.student)+planReviewBanner(p.savedPlan)+`<div class="planner-columns"><div>${card('开课与推荐',`<div class="tip space-b">${(p.notes||[]).map(html).join('<br>')||'课程推荐综合培养要求、未完成课程与当前学习负荷。'}<br>${p.dataMode==='demo'?'课表时段、先修关系与容量为演示数据，实际选课以教务系统公布信息为准。':''}</div>${p.recommended?.courseIds?.length&&!readOnly?`<div class="button-row space-b"><button class="btn" data-action="use-recommendation">${ico('assistant')}采用推荐组合（${p.recommended.courseIds.length} 门 / ${number(p.recommended.totalCredits,1)} 分）</button></div>`:''}<div class="offering-filters"><label class="search">${ico('search')}<input class="field" id="offering-query" placeholder="搜索课程名称 / 代码" aria-label="搜索开课课程"></label><select id="offering-filter" aria-label="筛选课程">${[['unfinished','未完成课程'],['recommended','推荐课程'],['selected','已选组合'],['required','必修课程'],['all','全部开课']].map(([value,label])=>`<option value="${value}" ${value===S.ws.offeringFilter?'selected':''}>${label}</option>`).join('')}</select></div><div id="offering-list"></div><div id="offering-pagination" class="table-bottom"></div>`,'可以手动选择课程，再核对组合是否适合')}${card('组合检查结果',`<div id="plan-check-result">${checkMarkup(S.ws.planningCheck)}</div>`,'检查时间冲突、先修条件、课程容量与计划学期')}${reviewForm(p.savedPlan,id,p.term)}</div><aside class="planner-summary">${card(readOnly?'我已提交的组合':'我的课程组合',`<div id="selection-summary">${selectionSummary()}</div>`,'保存草案与提交审核是两个独立步骤')}</aside></div>`;}

async function submissions(){const d=await request('/api/counselor/plans');S.ws.submissions=d.items||[];const pending=d.items.filter(p=>p.status==='submitted'),revision=d.items.filter(p=>p.status==='revision'),approved=d.items.filter(p=>p.status==='approved');return heading('学生选课方案','读懂学生的安排，给出可以落实的调整建议。')+`<div class="stats">${stat('待查看方案',pending.length,'份','学生已提交，等待你的反馈','curriculum','gold')}${stat('需要调整',revision.length,'份','已给出具体调整意见','alert')}${stat('已认可',approved.length,'份','规划已完成本轮沟通','check','blue')}${stat('全部方案',d.items.length,'份','包含已保存与提交的方案','ledger')}</div><section class="card"><div class="card-head"><h2>方案与审核记录</h2><select id="submission-filter" style="width:165px" aria-label="方案状态"><option value="">全部方案</option><option value="submitted">待查看</option><option value="revision">需要调整</option><option value="approved">已认可</option><option value="draft">草案</option></select></div><div class="table-scroll"><table><thead><tr><th>学生</th><th>学期 / 方案</th><th>状态</th><th>更新于</th><th>操作</th></tr></thead><tbody id="submission-rows">${submissionRows(d.items)}</tbody></table></div>${d.items.length?'':empty('暂时没有学生提交选课方案')}</section>`;}
function submissionRows(rows){return rows.map(p=>`<tr><td>${person(p.studentName,p.studentId)}</td><td>${html(p.title||'学期选课方案')}<small style="display:block" class="muted">${html(p.term)}</small></td><td><span class="badge ${p.status==='submitted'||p.status==='revision'?'level2':''}">${html(planStatus[p.status]||p.status)}</span></td><td class="small muted">${date(p.updatedAt)}</td><td><button class="btn link" data-action="open-planner" data-student="${html(p.studentId)}" data-term="${html(p.term)}">查看并反馈 ${ico('next')}</button></td></tr>`).join('');}
function plannerSelectionChanged(){S.ws.planningCheck=null;S.ws.planDirty=true;stashPlanDraft();if($('#selection-summary')){$('#selection-summary').innerHTML=selectionSummary();if(S.ws.planBusy)$$('button,input,textarea',$('#selection-summary')).forEach(el=>el.disabled=true);}if($('#plan-check-result'))$('#plan-check-result').innerHTML=checkMarkup(null);renderOfferings();}
async function checkSelection(){const p=S.ws.planning,ids=[...S.ws.selection],id=S.ws.planStudent;const result=await request(apiStudent(id)+'/planning/check',{method:'POST',body:JSON.stringify({term:p.term,courseIds:ids})});if(S.ws.planStudent!==id||JSON.stringify(ids)!==JSON.stringify(S.ws.selection))return result;S.ws.planningCheck=result;if($('#plan-check-result'))$('#plan-check-result').innerHTML=checkMarkup(result);return result;}
async function saveSelection(){const p=S.ws.planning,id=S.ws.planStudent,courseIds=[...S.ws.selection];const saved=await request(apiStudent(id)+'/planning',{method:'PUT',body:JSON.stringify({term:p.term,courseIds,title:S.ws.planTitle||'我的学期选课方案',note:S.ws.planNote||''})});if(id===S.ws.planStudent){p.savedPlan=saved;S.ws.planningCheck=saved.check||S.ws.planningCheck;S.ws.planDirty=false;if(S.ws.planDrafts)delete S.ws.planDrafts[id+'|'+p.term];if($('#selection-summary')){$('#selection-summary').innerHTML=selectionSummary();if(S.ws.planBusy)$$('button,input,textarea',$('#selection-summary')).forEach(el=>el.disabled=true);}if($('#plan-check-result'))$('#plan-check-result').innerHTML=checkMarkup(S.ws.planningCheck);}return saved;}

// Student-managed actions and counselor assignments.
function taskRow(t){const editable=['self','assistant'].includes(t.source||'self')&&(!t.assignedBy||t.assignedBy===S.user.id),today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'}),late=t.dueDate&&t.dueDate<today&&!t.completed;return `<article class="task-item ${t.completed?'completed':''}"><button class="task-check ${t.completed?'completed':''}" data-action="task-toggle" data-id="${html(t.id)}" data-complete="${!t.completed}" aria-label="${t.completed?'重新开启':'完成'}${html(t.title)}" aria-pressed="${t.completed}">${t.completed?ico('check'):''}</button><div class="task-content"><h3>${html(t.title)}</h3>${t.description?`<p>${html(t.description)}</p>`:''}<div class="task-meta"><span>${html(taskSources[t.source]||'我的计划')}${t.assignedName?' · '+html(t.assignedName):''}</span><span class="${late?'overdue':''}">${t.dueDate?(late?'已到期 · ':'计划完成 ')+html(t.dueDate):'未设截止日期'}</span></div>${t.alertId?`<button class="btn link" style="font-size:11px;margin-top:6px" data-action="alert" data-id="${html(t.alertId)}">查看关联预警 ${ico('next')}</button>`:''}</div><div class="task-actions">${editable?`<button class="icon-btn" data-action="edit-task" data-id="${html(t.id)}" aria-label="编辑${html(t.title)}">${ico('settings')}</button><button class="icon-btn" data-action="archive-task" data-id="${html(t.id)}" aria-label="归档${html(t.title)}">${ico('close')}</button>`:''}</div></article>`;}
function taskRows(){const tasks=S.ws.tasks||[],filter=S.ws.taskFilter;const rows=tasks.filter(t=>filter==='all'||filter==='done'&&t.completed||filter==='active'&&!t.completed);return rows.map(taskRow).join('')||empty(filter==='done'?'还没有已完成的行动，完成后可以在这里回顾。':'当前清单已经完成，给自己安排一个新的小目标吧。');}
async function plan(){const d=await request('/api/my/plan');S.ws.tasks=d.tasks||[];const completed=d.tasks.filter(t=>t.completed).length,ratio=d.tasks.length?Math.round(completed/d.tasks.length*100):0;return heading('我的行动计划','把建议拆成能做到的小事，记录自己的进步。',`<button class="btn" data-action="ask" data-question="请结合我的学情，生成一份可以采纳的学习行动计划。" data-student="${html(S.user.id)}">${ico('assistant')}让知学帮我拟计划</button>`)+`<div class="task-progress"><h2>${completed} 项已完成，${d.tasks.length-completed} 项在路上</h2><p>保持适合自己的节奏。来自辅导员的行动安排也会显示在这里，完成后会通知老师。</p><div class="progress"><i style="width:${ratio}%"></i></div></div><div class="grid2"><section>${card('添加一项学习行动',`<form id="task-create"><div class="form-grid"><label class="form-item full">我准备做什么<input class="field" name="title" required maxlength="120" placeholder="例如：周三前完成数据结构第三章错题复盘"></label><label class="form-item full">具体怎么做（可选）<textarea name="description" maxlength="1500" placeholder="写下练习范围、完成标准，或者需要谁的帮助。"></textarea></label><label class="form-item full">计划完成日期（可选）<input class="field" name="dueDate" type="date"></label></div><div class="form-actions"><button class="btn primary" type="submit">${ico('check')}添加行动</button></div><div class="form-error"></div></form>`,'可以随时编辑自己的计划，已不适用的行动可以归档')}<div class="tip" style="margin-top:18px">先做一件具体的事：写清楚内容、时间和完成标准，比“我要好好学习”更容易坚持。</div></section>${card('我的行动清单',`<div class="segmented space-b">${[['active','进行中'],['done','已完成'],['all','全部']].map(([id,n])=>`<button data-action="task-filter" data-id="${id}" class="${S.ws.taskFilter===id?'active':''}">${n}</button>`).join('')}</div><div id="task-list" class="task-list">${taskRows()}</div>`,'勾选表示行动完成；归档不会删除已有记录')}</div>`;}
function taskEditor(t){layer('调整我的行动',`<form id="task-editor" data-id="${html(t.id)}"><div class="form-grid"><label class="form-item full">行动内容<input class="field" name="title" required maxlength="120" value="${html(t.title)}"></label><label class="form-item full">具体做法<textarea name="description" maxlength="1500">${html(t.description||'')}</textarea></label><label class="form-item full">计划完成日期<input class="field" type="date" name="dueDate" value="${html(t.dueDate||'')}"></label></div><div class="form-actions"><button class="btn primary" type="submit">保存修改</button></div><div class="form-error"></div></form>`,true);}
function assignmentForm(id,alertId){layer('安排一项学习行动',`<p class="small muted space-b">${html(id)} · 保存后，学生可在自己的行动计划中查看、完成并反馈进度。</p><form id="task-assignment" data-student="${html(id)}" data-alert="${html(alertId||'')}"><div class="form-grid"><label class="form-item full">行动内容<input class="field" name="title" required maxlength="120" placeholder="例如：完成两套算法练习并整理不理解的题目"></label><label class="form-item full">具体说明<textarea name="description" maxlength="1500" placeholder="说明范围、完成标准，以及可以获得的支持。"></textarea></label><label class="form-item full">建议完成日期<input class="field" name="dueDate" type="date"></label></div><div class="form-actions"><button class="btn primary" type="submit">${ico('send')}发送给学生</button></div><div class="form-error"></div></form>`,true);}
async function notifications(){const token=layer('反馈与站内通知','<div class="skeleton"></div>');try{const d=await request('/api/notifications');if(token!==S.ws.overlayTicket)return;$('.drawer-body').innerHTML=`<div class="section-top"><div><h3>${d.unread} 条未读消息</h3><p class="small muted">预警、学习行动与选课方案的进展都汇集在这里。</p></div>${d.unread?`<button class="btn compact" data-action="read-all">全部标记已读</button>`:''}</div>${d.items.map(n=>`<article class="notice ${n.read?'notification-read':''}"><h3>${n.studentName?html(n.studentName)+' · ':''}${html(n.title)}</h3><p>${date(n.createdAt)}　${n.read?'已读':'未读'}</p><div class="button-row"><button class="btn compact" data-action="notification-open" data-kind="${html(n.kind||'alert')}" data-entity="${html(n.entityId||n.alertId||'')}" data-student="${html(n.studentId||'')}" data-alert="${html(n.alertId||'')}" data-id="${html(n.id)}">查看进展 ${ico('next')}</button>${!n.read?`<button class="btn compact" data-action="read" data-id="${html(n.id)}">标记已读</button>`:''}</div></article>`).join('')||empty('目前没有新的通知')}`;}catch(e){if(token===S.ws.overlayTicket)$('.drawer-body').innerHTML=inlineFailure(e);}}
async function analytics(){const d=await request('/api/analytics');S.analytics=d;S.view=Math.max(0,Math.min(S.view,(d.views||[]).length-1));const v=d.views[S.view];const anomalies=v.anomalies||[];return heading('群体洞察','观察相似学习状态与值得留意的变化，安排更有针对性的支持。')+`<div class="segmented settings-nav" role="tablist" aria-label="画像维度">${d.views.map((x,i)=>`<button role="tab" aria-selected="${i===S.view}" data-action="view" data-index="${i}" class="${i===S.view?'active':''}">${html(x.name)}</button>`).join('')}</div>${card(html(v.name),`<p class="small muted">${html(v.description)}</p><div class="tags space-b"><span class="tag">${html(v.method||'学情分组')}</span>${v.sampleCount!=null?`<span class="tag">${v.sampleCount} 位可见学生</span>`:''}${v.missingCount?`<span class="tag">${v.missingCount} 条数据需补充</span>`:''}${v.features?.length?`<span class="tag">${v.features.length} 个观察指标</span>`:''}</div><div class="grid3">${v.groups.map((g,groupIndex)=>`<article class="group-card"><h3>${html(g.name)}</h3><div class="group-count">${g.count}<small>位同学</small></div><p>${html(g.description)}</p><div class="group-people">${(g.students||[]).slice(0,12).map(s=>`<button data-action="profile" data-id="${html(s.id)}">${html(s.name)}</button>`).join('')}${g.students?.length>12?`<button class="btn link" data-action="group-members" data-group="${groupIndex}">查看全部 ${g.students.length} 位 ${ico('next')}</button>`:''}</div></article>`).join('')}</div>`,'只展示当前账号权限范围内的学生')}${card('需要进一步了解的个体',anomalies.length?anomalies.slice(0,8).map(s=>`<div class="row"><div>${person(s.name,s.id)}<p class="small muted" style="margin-top:8px">${html(s.reason||s.label||'在当前观察维度中与群体存在差异，建议结合具体情况了解。')}</p></div><button class="btn link" data-action="profile" data-id="${html(s.id)}">查看画像 ${ico('next')}</button></div>`).join(''):empty('当前没有标记为异常观察的学生'),'辅助观察不等于学业问题，也不会自动提高正式预警等级')}<p class="source">${html(d.note)}</p><div id="forecast-panel"></div>`;}

const workspaceActions=new Set(['menu','mobile-nav-close','new-thread','thread','apply-proposal','open-planner','students-page','use-recommendation','remove-course','offer-prev','offer-next','check-plan','save-plan','submit-plan','planner-audit','edit-task','archive-task','confirm-archive','task-filter','task-toggle','assign-task','read-all','notification-open','switch-term-draft','switch-term-save','discard-followup-draft','group-members','forecast-prev','forecast-next']);
async function planOperation(action){if(S.ws.planBusy){toast('正在保存或检查当前组合，请稍等');return;}S.ws.planBusy=true;const controls=$$('[data-course],#plan-title,#plan-note,[data-action="check-plan"],[data-action="save-plan"],[data-action="submit-plan"],[data-action="use-recommendation"],[data-action="remove-course"]');controls.forEach(el=>el.disabled=true);try{if(action==='check-plan'){await checkSelection();toast('组合检查已完成');$('#plan-check-result')?.scrollIntoView({behavior:'smooth',block:'center'});}if(action==='save-plan'){await saveSelection();toast('选课草案已保存');}if(action==='submit-plan'){const result=await checkSelection();if(!result.eligible){toast('请先解决组合检查中的问题，再提交');$('#plan-check-result')?.scrollIntoView({behavior:'smooth',block:'center'});return;}await saveSelection();const p=S.ws.planning;await request(apiStudent(S.ws.planStudent)+'/planning/submit',{method:'POST',body:JSON.stringify({term:p.term})});toast('方案已提交给负责辅导员');await go('planner');}}finally{S.ws.planBusy=false;if(S.page==='planner'&&$('#selection-summary'))$('#selection-summary').innerHTML=selectionSummary();controls.forEach(el=>{if(el.isConnected)el.disabled=false;});}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||!workspaceActions.has(el.dataset.action))return;e.stopImmediatePropagation();e.preventDefault();if(el.dataset.pending==='true')return;el.dataset.pending='true';el.disabled=true;const action=el.dataset.action;try{
  if(action==='discard-followup-draft'){const form=$('#followup');if(form){form.dataset.draftDirty='false';clearFollowupDraft(form.dataset.id);await openAlert(form.dataset.id);}}
  if(action==='forecast-prev'||action==='forecast-next'){S.ws.forecastPage+=(action==='forecast-next'?1:-1);drawForecast();}
  if(action==='group-members')showGroupMembers(Number(el.dataset.group));
  if(action==='menu'){setMobileNavigation(!$('.app-frame')?.classList.contains('menu-open'),true);}
  if(action==='mobile-nav-close')setMobileNavigation(false,true);
  if(action==='switch-term-draft'||action==='switch-term-save'){if(action==='switch-term-save')await saveSelection();S.ws.planTerm=S.ws.pendingTerm;S.ws.pendingTerm=null;await go('planner');}
  if(action==='new-thread'){if(S.ws.chatBusy)throw new Error('请等当前回答完成后再开始新对话');S.ws.threadId=null;S.ws.chatContext=null;S.ws.messages=[];S.ws.chatDraft='';S.ws.forceNew=true;rememberThread();await go('assistant');}
  if(action==='thread'){if(S.ws.chatBusy)throw new Error('请等当前回答完成后再切换对话');const ticket=(S.ws.conversationTicket||0)+1;S.ws.conversationTicket=ticket;await loadConversation(el.dataset.id,ticket);if(ticket===S.ws.conversationTicket)await go('assistant');}
  if(action==='apply-proposal'){const d=await request('/api/assistant/proposals/'+encodeURIComponent(el.dataset.id)+'/apply',{method:'POST'});S.ws.messages.forEach(m=>(m.proposals||[]).forEach(p=>{if(p.id===el.dataset.id)p.status='applied';}));renderConversation();toast(d.alreadyApplied?'这份草案已经采纳，无需重复添加':`已添加 ${d.appliedCount} 项学习行动`);}
  if(action==='open-planner'){S.ws.planStudent=el.dataset.student||S.user.id;S.ws.planTerm=el.dataset.term||null;await go('planner');}
  if(action==='students-page')await go('students');
  if(action==='use-recommendation'){S.ws.selection=[...(S.ws.planning.recommended?.courseIds||[])];plannerSelectionChanged();toast('推荐组合已放入选课清单，可继续调整');}
  if(action==='remove-course'){S.ws.selection=S.ws.selection.filter(id=>id!==el.dataset.id);plannerSelectionChanged();}
  if(action==='offer-prev'||action==='offer-next'){S.ws.offeringsPage+=action==='offer-next'?1:-1;renderOfferings();$('#offering-list')?.scrollIntoView({behavior:'smooth',block:'start'});}
  if(['check-plan','save-plan','submit-plan'].includes(action))await planOperation(action);
  if(action==='planner-audit'){const a=S.ws.audit;layer('培养路径与要求',preferencesForm(a,S.user.role==='counselor')+auditCheckList(a.checks)+(a.moduleAudits||[]).filter(m=>m.selected).map(auditModule).join(''));}
  if(action==='edit-task'){const task=(S.ws.tasks||[]).find(t=>String(t.id)===el.dataset.id);if(task)taskEditor(task);}
  if(action==='archive-task'){const task=(S.ws.tasks||[]).find(t=>String(t.id)===el.dataset.id);if(task)layer('归档这项行动',`<p class="small">${html(task.title)}</p><p class="source">归档后会从当前行动清单移除，已有记录仍会保留。辅导员安排的行动不能自行归档。</p><div class="form-actions"><button class="btn" data-action="close">保留行动</button><button class="btn primary" data-action="confirm-archive" data-id="${html(task.id)}">归档</button></div>`,true);}
  if(action==='confirm-archive'){await request('/api/my/plan/'+encodeURIComponent(el.dataset.id),{method:'DELETE'});close();toast('行动已归档');await go('plan');}
  if(action==='task-filter'){S.ws.taskFilter=el.dataset.id;$$('[data-action="task-filter"]').forEach(b=>b.classList.toggle('active',b===el));$('#task-list').innerHTML=taskRows();}
  if(action==='task-toggle'){await request('/api/my/plan/'+encodeURIComponent(el.dataset.id),{method:'PATCH',body:JSON.stringify({completed:el.dataset.complete==='true'})});toast(el.dataset.complete==='true'?'已记录完成，继续保持自己的节奏':'行动已重新开启');await go(S.page==='mine'?'mine':'plan');}
  if(action==='assign-task')assignmentForm(el.dataset.student,el.dataset.alert);
  if(action==='read-all'){await request('/api/notifications/read-all',{method:'POST'});await notifications();}
  if(action==='notification-open'){await request('/api/notifications/'+encodeURIComponent(el.dataset.id)+'/read',{method:'POST'});const kind=el.dataset.kind;if(kind==='semester_plan'){S.ws.planStudent=el.dataset.student||S.user.id;S.ws.planTerm=null;await go('planner');}else if(kind==='study_task'){if(S.user.role==='student')await go('plan');else await openProfile(el.dataset.student);}else if(el.dataset.alert||el.dataset.entity){await openAlert(el.dataset.alert||el.dataset.entity);}else{toast('已标记为已读');await notifications();}}
}catch(err){toast(err.message);}finally{delete el.dataset.pending;if(el.isConnected)el.disabled=false;}},true);

const workspaceForms=new Set(['conversation-form','curriculum-preferences','plan-review','task-create','task-editor','task-assignment','followup','student-feedback']);
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement)||!workspaceForms.has(form.id))return;e.preventDefault();e.stopImmediatePropagation();if(form.dataset.pending==='true')return;form.dataset.pending='true';const submit=form.querySelector('[type="submit"]'),data=new FormData(form);if(submit)submit.disabled=true;const error=form.querySelector('.form-error,.inline-error');if(error)error.textContent='';try{
  if(form.id==='followup'){const token=S.ws.overlayTicket,body=Object.fromEntries(data);body.note=String(body.note||'').trim();if(!body.note)throw new Error('请填写本次联系或处理情况');const id=form.dataset.id;await request('/api/alerts/'+encodeURIComponent(id)+'/followup',{method:'POST',body:JSON.stringify(body)});form.dataset.draftDirty='false';clearFollowupDraft(id);S.dirty=true;toast('跟进记录已保存，台账已更新');if(token===S.ws.overlayTicket)await openAlert(id);}
  if(form.id==='student-feedback'){const token=S.ws.overlayTicket,note=String(data.get('note')||'').trim(),id=form.dataset.id;if(note.length<2)throw new Error('请填写具体反馈内容');await request('/api/alerts/'+encodeURIComponent(id)+'/feedback',{method:'POST',body:JSON.stringify({note})});toast('反馈已记录，负责辅导员可以查看');if(token===S.ws.overlayTicket)await openAlert(id);}
  if(form.id==='conversation-form'){const message=String(data.get('message')||'').trim();if(message)await ask(message);}
  if(form.id==='curriculum-preferences'){let allocations={...(S.ws.audit?.preferences?.allocations||{})};for(const [key,value]of data.entries()){if(key.startsWith('allocation:')){const id=key.slice(11);if(value)allocations[id]=value;else delete allocations[id];}}const chosen=data.getAll('advancedModules');allocations=validAllocations(allocations,S.ws.audit?.advancedModules||[],chosen);const body={language:data.get('language'),path:data.get('path'),advancedModules:chosen,allocations};await request(apiStudent(form.dataset.student)+'/curriculum-preferences',{method:'PUT',body:JSON.stringify(body)});toast('培养路线已保存，已更新核算结果');await go(S.page==='planner'?'planner':'credits');}
  if(form.id==='plan-review'){const body={term:form.dataset.term,status:data.get('status'),comment:String(data.get('comment')||'').trim()};if(!body.comment)throw new Error('请填写给学生的具体意见');await request(apiStudent(form.dataset.student)+'/planning/review',{method:'POST',body:JSON.stringify(body)});toast('审核意见已反馈给学生');await go('planner');}
  if(['task-create','task-editor','task-assignment'].includes(form.id)){const body=Object.fromEntries(data);body.title=String(body.title||'').trim();if(!body.title)throw new Error('请填写具体行动内容');if(form.id==='task-assignment'){if(form.dataset.alert)body.alertId=form.dataset.alert;await request(apiStudent(form.dataset.student)+'/plan',{method:'POST',body:JSON.stringify(body)});toast('学习行动已发送给学生');const id=form.dataset.student;close();await openProfile(id);}else{await request('/api/my/plan'+(form.id==='task-editor'?'/'+encodeURIComponent(form.dataset.id):''),{method:form.id==='task-editor'?'PATCH':'POST',body:JSON.stringify(body)});toast(form.id==='task-editor'?'行动已更新':'学习行动已添加');close();await go('plan');}}
}catch(err){if(error&&error.isConnected)error.textContent=err.message;else toast(err.message);}finally{delete form.dataset.pending;if(submit?.isConnected)submit.disabled=false;}},true);

document.addEventListener('input',e=>{if(e.target.closest('#followup')){e.target.form.dataset.draftDirty='true';stashFollowupDraft();}if(e.target.id==='forecast-query'){S.ws.forecastQuery=e.target.value;S.ws.forecastPage=1;drawForecast();}if(e.target.id==='allocation-query')filterAllocationRows(e.target.value);if(e.target.id==='group-member-query')filterGroupMembers(e.target.value);if(e.target.id==='offering-query'){S.ws.offeringQuery=e.target.value;S.ws.offeringsPage=1;renderOfferings();}if(e.target.id==='plan-title'){S.ws.planTitle=e.target.value;stashPlanDraft();}if(e.target.id==='plan-note'){S.ws.planNote=e.target.value;stashPlanDraft();}if(e.target.closest('#conversation-form')&&e.target.name==='message')S.ws.chatDraft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.closest('#followup')){e.target.form.dataset.draftDirty='true';stashFollowupDraft();}if(e.target.closest('#curriculum-preferences')&&(e.target.name==='advancedModules'||e.target.name?.startsWith('allocation:')))reconcileAllocations();if(e.target.id==='planning-term'){const term=e.target.value,current=S.ws.planning.term;const draft=(S.ws.planDrafts||{})[S.ws.planStudent+'|'+current];if(draft?.dirty){e.target.value=current;S.ws.pendingTerm=term;layer('切换规划学期',`<p class="small">当前学期有尚未保存的调整。</p><p class="source">保存后再切换，稍后回来可以继续查看；也可以将当前调整暂留在本次会话中。</p><div class="form-actions"><button class="btn" data-action="close">继续编辑</button><button class="btn" data-action="switch-term-draft">暂存并切换</button><button class="btn primary" data-action="switch-term-save">保存并切换</button></div>`,true);}else{S.ws.planTerm=term;go('planner');}return;}if(e.target.matches('[data-course]')){if(S.ws.planBusy){e.target.checked=S.ws.selection.includes(e.target.dataset.course);return;}const id=e.target.dataset.course;if(e.target.checked)S.ws.selection=[...new Set([...S.ws.selection,id])];else S.ws.selection=S.ws.selection.filter(x=>x!==id);plannerSelectionChanged();}if(e.target.id==='offering-filter'){S.ws.offeringFilter=e.target.value;S.ws.offeringsPage=1;renderOfferings();}if(e.target.id==='submission-filter')$('#submission-rows').innerHTML=submissionRows(S.ws.submissions.filter(p=>!e.target.value||p.status===e.target.value));if(e.target.matches('#curriculum-preferences [name="path"]')){const p=S.ws.audit?.paths?.find(p=>p.id===e.target.value);const note=$('#curriculum-preferences .module-path-summary');if(note&&p)note.textContent=p.description||'';}});
document.addEventListener('keydown',e=>{if(e.target.matches('#conversation-form textarea')&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();e.target.form.requestSubmit();}});

boot();
